WITH scored AS (SELECT *, LEAD(balance, 2) OVER (PARTITION BY account_type ORDER BY balance, id) AS next_balance, NTILE(10) OVER (ORDER BY balance, id) AS balance_bucket, CUME_DIST() OVER w_grp AS balance_cume_dist FROM accounts WINDOW w_grp AS (PARTITION BY account_type, customer_id ORDER BY balance NULLS LAST)), joined AS (SELECT e.*, p.signup_date, p.credit_limit FROM scored e LEFT JOIN customers p ON e.customer_id = p.id), remaining_keys AS (SELECT account_type FROM joined EXCEPT SELECT account_type FROM accounts WHERE status IN ('FROZEN', 'OPEN')), verified AS (SELECT s.* FROM joined s JOIN remaining_keys k ON s.account_type = k.account_type), with_windows AS (SELECT *, SUM(balance_bucket) OVER w_part AS status_sum_balance_bucket, CUME_DIST() OVER w_part_2 AS balance_cume_dist_2, MIN(balance_cume_dist) OVER w_grp AS account_type_min_balance_cume_dist, MAX(next_balance) OVER (PARTITION BY status) AS status_max_next_balance, RANK() OVER (PARTITION BY account_type ORDER BY next_balance DESC NULLS LAST) AS next_balance_rank FROM verified WINDOW w_part AS (PARTITION BY status, customer_id), w_part_2 AS (PARTITION BY customer_id, status ORDER BY balance DESC NULLS FIRST), w_grp AS (PARTITION BY account_type)), with_dims AS (SELECT a.*, c.name, c.credit_limit AS customer_credit_limit FROM with_windows a LEFT JOIN customers c ON a.customer_id = c.id), scored_accounts AS (SELECT id, customer_id, account_type, balance, opened_date, status, next_balance, balance_bucket, balance_cume_dist, signup_date, credit_limit, status_sum_balance_bucket, balance_cume_dist_2, account_type_min_balance_cume_dist, status_max_next_balance, next_balance_rank, name, customer_credit_limit, RANK() OVER (PARTITION BY customer_id, status ORDER BY next_balance DESC) AS next_balance_rank_2, MIN(customer_credit_limit) OVER (PARTITION BY status) AS status_min_customer_credit_limit, RANK() OVER (PARTITION BY status ORDER BY status_max_next_balance DESC) AS status_max_next_balance_rank FROM with_dims) SELECT *, SUM(status_max_next_balance) OVER w_grp AS customer_id_sum_status_max_next_balance, DENSE_RANK() OVER w_recent AS status_sum_balance_bucket_dense_rank, RANK() OVER (PARTITION BY customer_id ORDER BY balance_cume_dist DESC NULLS FIRST) AS balance_cume_dist_rank, PERCENT_RANK() OVER w_recent_2 AS next_balance_percent_rank, DENSE_RANK() OVER (ORDER BY credit_limit DESC NULLS LAST) AS credit_limit_dense_rank FROM scored_accounts WINDOW w_grp AS (PARTITION BY customer_id), w_recent AS (PARTITION BY status ORDER BY status_sum_balance_bucket DESC NULLS LAST), w_recent_2 AS (PARTITION BY account_type, status ORDER BY next_balance DESC NULLS LAST);
